const {chromium}=require('playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,args:['--no-sandbox']});
 const page=await browser.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true});
 const errors=[];
 page.on('pageerror',e=>errors.push(e.message));
 await page.goto('https://theascendtheory.github.io/the-ascend-theory/',{waitUntil:'domcontentloaded',timeout:45000});
 await page.getByRole('heading',{name:'Explore the network'}).waitFor({timeout:30000});
 if(await page.locator('input#email').count())throw Error('Email is gating public exploration');
 await page.getByRole('heading',{name:'Global activity map'}).waitFor();
 await page.locator('.hub-map iframe').first().waitFor();
 await page.getByRole('button',{name:'Projects',exact:true}).first().click();
 await page.locator('#projectSearch').waitFor();
 await page.locator('#projectSearch').fill('education');
 await page.getByRole('button',{name:'People',exact:true}).first().click();
 await page.getByRole('heading',{name:'People directory'}).waitFor();
 await page.getByRole('button',{name:'Apply to join'}).click();
 await page.locator('#email').waitFor();
 await page.getByRole('button',{name:'Back to exploration'}).click();
 await page.getByRole('heading',{name:'People & collaboration'}).waitFor();
 if(errors.length)throw Error('JavaScript errors: '+errors.join('; '));
 await page.screenshot({path:'/tmp/ascend-hub-mobile.png',fullPage:true});
 console.log('PASS: Public dashboard, live map, search, people and gated join work on mobile.');
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
